488: void warp_inst_t::memory_coalescing_arch(bool is_write,
489:                                          mem_access_type access_type) {
490:   // see the CUDA manual where it discusses coalescing rules before reading this
491:   unsigned segment_size = 0;
492:   unsigned warp_parts = m_config->mem_warp_parts;
493:   bool sector_segment_size = false;
494: 
495:   if (m_config->gpgpu_coalesce_arch >= 20 &&
496:       m_config->gpgpu_coalesce_arch < 39) {
497:     // Fermi and Kepler, L1 is normal and L2 is sector
498:     if (m_config->gmem_skip_L1D || cache_op == CACHE_GLOBAL)
499:       sector_segment_size = true;
500:     else
501:       sector_segment_size = false;
502:   } else if (m_config->gpgpu_coalesce_arch >= 40) {
503:     // Maxwell, Pascal and Volta, L1 and L2 are sectors
504:     // all requests should be 32 bytes
505:     sector_segment_size = true;
506:   }
507: 
508:   switch (data_size) {
509:     case 1:
510:       segment_size = 32;
511:       break;
512:     case 2:
513:       segment_size = sector_segment_size ? 32 : 64;
514:       break;
515:     case 4:
516:     case 8:
517:     case 16:
518:       segment_size = sector_segment_size ? 32 : 128;
519:       break;
520:   }
521:   unsigned subwarp_size = m_config->warp_size / warp_parts;
522: 
523:   for (unsigned subwarp = 0; subwarp < warp_parts; subwarp++) {
524:     std::map<new_addr_type, transaction_info> subwarp_transactions;
525: 
526:     // step 1: find all transactions generated by this subwarp
527:     for (unsigned thread = subwarp * subwarp_size;
528:          thread < subwarp_size * (subwarp + 1); thread++) {
529:       if (!active(thread)) continue;
530: 
531:       unsigned data_size_coales = data_size;
532:       unsigned num_accesses = 1;
533: 
534:       if (space.get_type() == local_space ||
535:           space.get_type() == param_space_local) {
536:         // Local memory accesses >4B were split into 4B chunks
537:         if (data_size >= 4) {
538:           data_size_coales = 4;
539:           num_accesses = data_size / 4;
540:         }
541:         // Otherwise keep the same data_size for sub-4B access to local memory
542:       }
543: 
544:       assert(num_accesses <= MAX_ACCESSES_PER_INSN_PER_THREAD);
545: 
546:       //            for(unsigned access=0; access<num_accesses; access++) {
547:       // Build addresses from either m_per_scalar_thread[thread].memreqaddr or
548:       // m_tma_access_addrs
549:       std::vector<new_addr_type> addresses;
550:       if (is_tma()) {
551:         addresses = m_tma_access_addrs;
552:       } else {
553:         assert(m_per_scalar_thread[thread].memreqaddr.size() <=
554:                MAX_ACCESSES_PER_INSN_PER_THREAD);
555:         addresses = m_per_scalar_thread[thread].memreqaddr;
556:       }
557: 
558:       // Iterate over addresses for coalescing
559:       for (auto &addr : addresses) {
560:         new_addr_type block_address =
561:             line_size_based_tag_func(addr, segment_size);
562:         unsigned chunk =
563:             (addr & 127) / 32;  // which 32-byte chunk within in a 128-byte
564:                                 // chunk does this thread access?
565:         transaction_info &info = subwarp_transactions[block_address];
566: 
567:         // can only write to one segment
568:         // it seems like in trace driven, a thread can write to more than one
569:         // segment assert(block_address ==
570:         // line_size_based_tag_func(addr+data_size_coales-1,segment_size));
571: 
572:         info.chunks.set(chunk);
573:         info.active.set(thread);
574:         unsigned idx = (addr & 127);
575:         for (unsigned i = 0; i < data_size_coales; i++)
576:           if ((idx + i) < MAX_MEMORY_ACCESS_SIZE) info.bytes.set(idx + i);
577: 
578:         // it seems like in trace driven, a thread can write to more than one
579:         // segment handle this special case
580:         if (block_address != line_size_based_tag_func(
581:                                  addr + data_size_coales - 1, segment_size)) {
582:           addr = addr + data_size_coales - 1;
583:           new_addr_type block_address =
584:               line_size_based_tag_func(addr, segment_size);
585:           unsigned chunk = (addr & 127) / 32;
586:           transaction_info &info = subwarp_transactions[block_address];
587:           info.chunks.set(chunk);
588:           info.active.set(thread);
589:           unsigned idx = (addr & 127);
590:           for (unsigned i = 0; i < data_size_coales; i++)
591:             if ((idx + i) < MAX_MEMORY_ACCESS_SIZE) info.bytes.set(idx + i);
592:         }
593:       }
594:     }
595: 
596:     // step 2: reduce each transaction size, if possible
597:     std::map<new_addr_type, transaction_info>::iterator t;
598:     for (t = subwarp_transactions.begin(); t != subwarp_transactions.end();
599:          t++) {
600:       new_addr_type addr = t->first;
601:       const transaction_info &info = t->second;
602: 
603:       memory_coalescing_arch_reduce_and_send(is_write, access_type, info, addr,
604:                                              segment_size);
605:     }
606:   }
